head.b:skin:
/*-----------------------------------------------
BloggerEasy generated theme
Template: travel
-----------------------------------------------*/
body {
  margin: 0;
  font-family: Georgia;
  color: #222222;
  background: #ffffff;
  line-height: 1.6;
  overflow-wrap: anywhere;
}
a { color: #1c1917; }
img, iframe, video {
  max-width: 100%;
  height: auto;
}
.header-inner {
  background: #1c1917;
  color: #fff;
  padding: 1.5rem 1rem;
}
.header-inner h1, .header-inner a { color: #fff; text-decoration: none; font-family: system-ui; }
.nav-bar {
  background: #faf7f2;
  padding: 0.5rem 1rem;
}
.nav-bar ul { list-style: none; margin: 0; padding: 0; display: flex; gap: 1rem; flex-wrap: wrap; }
.nav-bar a { color: #fff; text-decoration: none; }
.content-wrap {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.25rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}
.magazine-featured {
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  padding: 0.75rem;
}
.post {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 2rem 1.25rem 3.5rem;
  margin-bottom: 1rem;
}
.post h3 { font-family: system-ui; margin-top: 0; }
.post a, .button, button {
  background: #1a73e8;
  color: #ffffff;
  padding: 0.55rem 0.9rem;
  border-radius: 6px;
}
.sidebar .widget {
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1rem;
}
.footer-inner {
  margin-top: 2rem;
  padding: 1rem;
  text-align: center;
  background: #0f172a;
  color: #e2e8f0;
  font-size: 0.9rem;
}
.landing-shell {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1rem 0;
}
.landing-hero {
  padding: 3rem 1.5rem;
  text-align: center;
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}
.landing-hero h1 {
  margin: 0 0 0.75rem;
  color: #222222;
  font-family: system-ui;
  font-size: 2.4rem;
}
.landing-hero p { max-width: 680px; margin: 0 auto 1.5rem; }
.landing-cta { display: inline-block; text-decoration: none; }
.landing-features {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
  padding: 2rem 0;
}
.landing-card {
  padding: 2rem 1.25rem 3.5rem;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}
.landing-card h2 { margin-top: 0; font-family: system-ui; }
@media (max-width: 800px) {
  .content-wrap { grid-template-columns: 1fr; }
  .landing-features { grid-template-columns: 1fr; }
  .landing-hero { padding: 2rem 1rem; }
  .landing-hero h1 { font-size: 1.9rem; }
  .header-inner { padding: 1rem; }
  .header-inner h1 { font-size: 1.65rem; line-height: 1.2; }
  .nav-bar ul { gap: 0.45rem; }
  .nav-bar a { display: inline-block; padding: 0.25rem 0; }
  .post { padding: 0.85rem; }
  .sidebar .widget { padding: 0.85rem; }
}
@media (max-width: 480px) {
  .content-wrap { padding: 0.5rem; }
  .nav-bar { padding: 0.45rem 0.65rem; }
  .nav-bar ul { flex-direction: column; gap: 0.25rem; }
  .footer-inner { font-size: 0.82rem; }
}
